#!/usr/bin/env bash
# TRACKED PORT of build/vivado/g1e_prep/test_v1cases_on_v2.sh: base reports from the compact nc3 fixture instead of build evidence.
# PORT of the frozen v1 harness (test_evaluate_g1.sh) to evaluate_g1_v2.sh: same cases and expectations; fixtures gain Timing Details
# blocks consistent with their rows (v2 cross-checks them). Offline qualification of evaluate_g1.sh. Run from the repository root:  test_evaluate_g1.sh SCRATCH_DIR
# Base evidence: real Step 7V NC3 run (build/vivado/step7v_nc3_01, original XDC = same netlist as the NC run). OUT/FAILED or COMPLETE is always
# regenerated by the CURRENT gate (regen_failed_g1.tcl; format proven byte-identical on Step 7V NC3).
# SYNTHETIC: every guard_clk row in the pos fixtures (no generated-clock run exists yet; row layout follows the observed report columns and the
# clock report's documented attribute legend 'G: Generated'). PREDICTED: the NC diagnostic text (Vivado's real message for an empty
# create_generated_clock target is not yet observed).
set -u
S="$1"; EV="${2:-tools/vivado/evaluate_g1_v2.sh}"; P=tools/vivado/tests/g1_evaluator; V=build/vivado; B=$P/fixtures/nc3/out; BD=$P/fixtures/nc3/det
FLOW=tools/vivado/spu_vivado_flow.tcl; LOADER=$P/load_procs.tcl
rm -rf "$S"; mkdir -p "$S"; fails=0
G1X=hardware/boards/artix7/spu_a7_tensegrity_link_g1.xdc; NCX=$P/fixtures/nc_wrong_object.xdc; ABS="$(pwd)/$NCX:35"
ident() { cat > "$S/ident_$1.env" <<EOF
GIT_HEAD=fixture0000000000000000000000000000000000
GIT_STATUS_SHA=e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855
GATE_SHA=$(sha256sum < $FLOW | cut -d' ' -f1)
FILELIST_SHA=20541782b709cbf5904fcaa4976891dd638225fca0d07ae037f31b2c956cab55
SOURCES_SHA=$(awk '/^source_sha256 /{print $2"  "$3}' $B/run_manifest.txt | sort | sha256sum | cut -d' ' -f1)
G1_XDC=$G1X
G1_XDC_SHA=$(sha256sum < $G1X | cut -d' ' -f1)
NC_XDC=$NCX
NC_XDC_SHA=$(sha256sum < $NCX | cut -d' ' -f1)
NC_XDC_LINE=35
ATTEMPT_LIMIT=900
CUM_LIMIT=1800
CUM_DIRS="$S/$1/det"
EOF
}
base() { # name xdc
    mkdir -p "$S/$1/out" "$S/$1/det"; cp $B/{vivado.log,synth_check_timing.rpt,run_manifest.txt,synth_clocks.rpt,synth_clock_networks.rpt,synth_timing_summary.rpt,synth_methodology.rpt,synth_drc.rpt,synth_utilization.rpt,synth_cdc.rpt} "$S/$1/out/"
    cp $BD/{exit_status,result.json} "$S/$1/det/"; ident "$1"
    sed -i -e "s#^git_head .*#git_head fixture0000000000000000000000000000000000#" -e "s#^git_status_sha256 .*#git_status_sha256 e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855#" \
           -e "s#^arg -xdc .*#arg -xdc $2#" -e "s#^xdc_sha256 .*#xdc_sha256 $(sha256sum < $2 | cut -d' ' -f1)#" \
           -e "s#^arg -expect_clock sys_clk:20.000#arg -expect_clock sys_clk:20.000\narg -expect_clock guard_clk:40.000#" "$S/$1/out/run_manifest.txt"; }
runner() { # name COMPLETE|FAILED
    rm -f "$S/$1/det/"{COMPLETE,FAILED,TIMEOUT}; echo t > "$S/$1/det/$2"; rc=$([ "$2" = COMPLETE ] && echo 0 || echo 1); echo $rc > "$S/$1/det/exit_status"
    sed -i -e "s/\"outcome\": \"[A-Z]*\"/\"outcome\": \"$2\"/" -e "s/\"exit_code\": [0-9]*/\"exit_code\": $rc/" "$S/$1/det/result.json"; }
regen() { tclsh $P/regen_failed_g1.tcl $FLOW $LOADER "$S/$1/out" "sys_clk:20.000 guard_clk:40.000" "$2"; runner "$1" "$([ -e $S/$1/out/COMPLETE ] && echo COMPLETE || echo FAILED)"; }
blk() { printf -- '---------------------------------------------------------------------------------------------------\nFrom Clock:  %s\n  To Clock:  %s\n\nSetup :  %11s  Failing Endpoints,  Worst Slack  %10sns,  Total Violation  %10sns\nHold  :  %11s  Failing Endpoints,  Worst Slack  %10sns,  Total Violation  %10sns\n---------------------------------------------------------------------------------------------------\n' "$@"; }
g1ify() { # make a pos fixture look like a G1 run (SYNTHETIC guard_clk rows)
    o="$S/$1/out"
    sed -i -e 's/checking no_clock (8172)/checking no_clock (0)/' -e 's/checking unconstrained_internal_endpoints (28651)/checking unconstrained_internal_endpoints (0)/' $o/synth_check_timing.rpt
    sed -i '/^sys_clk  20.000/a guard_clk  40.000      {0.000 20.000}  P,G         {guard_clk_div_reg/Q}' $o/synth_clocks.rpt
    sed -i -e '/^Clock Q (endpoints/d' -e '/^FDRE\/Q (guard_clk_div_reg)$/d' -e '/^Port sys_clk$/a \\nClock guard_clk (25MHz)(endpoints: 8172 clock, 1 nonclock)\nPin guard_clk_div_reg/Q' $o/synth_clock_networks.rpt
    sed -i '/^sys_clk            16.676/a guard_clk          12.000        0.000                      0                21000        0.050        0.000                      0                21000       19.500        0.000                       0                  8173  ' $o/synth_timing_summary.rpt
    awk '{print} /^----------    --------  /&&!d{print "sys_clk       guard_clk          15.000        0.000                      0                  300        0.200        0.000                      0                  300  "; d=1}' $o/synth_timing_summary.rpt > $S/t && mv $S/t $o/synth_timing_summary.rpt
    { blk guard_clk guard_clk 0 12.000 0.000 0 0.050 0.000; blk sys_clk guard_clk 0 15.000 0.000 0 0.200 0.000; } >> $o/synth_timing_summary.rpt
    sed -i '/^| TIMING-17 /d' $o/synth_methodology.rpt; }
nc_diag() { # name line-suffix kind
    case $3 in
      pair) printf "WARNING: [Vivado 12-584] No pins matched 'guard_clk_div_reg_x/Q'. [%s]\nCRITICAL WARNING: [Vivado 12-4739] create_generated_clock:No valid object(s) found for '-objects [get_pins guard_clk_div_reg_x/Q]'. [%s]\n" "$2" "$2";;
      warnonly) printf "WARNING: [Vivado 12-584] No pins matched 'guard_clk_div_reg_x/Q'. [%s]\n" "$2";;
      unmatched) printf "WARNING: [Vivado 12-584] No pins matched 'guard_clk_div_reg_x/Q'. [%s]\nCRITICAL WARNING: [Vivado 12-9999] create_generated_clock: hypothetical wording the gate does not know. [%s]\n" "$2" "$2";;
    esac > $S/ins; awk -v f=$S/ins '{print} /^Parsing XDC File/&&!d{while((getline l<f)>0) print l; d=1}' "$S/$1/out/vivado.log" > $S/t && mv $S/t "$S/$1/out/vivado.log"; }
run() { # name control expect-string
    out=$(bash $EV "$2" "$S/$1/out" "$S/$1/det" "$S/ident_$1.env" 2>&1); printf '%s\n' "$out" > "$S/$1.eval.txt"
    if [ "$2" = pos ]; then got="$(printf '%s\n' "$out" | grep -E '^DISPOSITION (COVERAGE|TIMING|GATE-POSITIVE) ' | awk '{print $2"="$3}' | tr '\n' ' ')$(printf '%s\n' "$out" | grep '^VERDICT' | awk '{print $3}')"
    else got="$(printf '%s\n' "$out" | grep '^VERDICT' | sed 's/^VERDICT nc //; s/ ([0-9]* failed checks)//')"; fi
    printf '%-34s %s  got: %s\n' "$1" "$([ "$got" = "$3" ] && echo OK || echo "BAD (want: $3)")" "$got"
    [ "$got" = "$3" ] || fails=$((fails+1)); }
PASS3="COVERAGE=PASS TIMING=NO-VIOLATION GATE-POSITIVE=PASS PROCEED"
# --- pos
base pos_synthetic_pass $G1X;   g1ify pos_synthetic_pass;   regen pos_synthetic_pass "sys_clk:20.000 guard_clk:40.000"; run pos_synthetic_pass pos "$PASS3"
base pos_timing_violation $G1X; g1ify pos_timing_violation; sed -i -e 's/^guard_clk          12.000        0.000                      0 /guard_clk          -1.500      -18.000                     12 /' -e '/^From Clock:  guard_clk$/{n;n;n;s/.*/Setup :           12  Failing Endpoints,  Worst Slack      -1.500ns,  Total Violation    -18.000ns/}' $S/pos_timing_violation/out/synth_timing_summary.rpt
                                regen pos_timing_violation "sys_clk:20.000 guard_clk:40.000"; run pos_timing_violation pos "COVERAGE=PASS TIMING=FAIL GATE-POSITIVE=PASS PROCEED"
base pos_reverse_row $G1X;      g1ify pos_reverse_row;      awk '{print} /^sys_clk       guard_clk/{print "guard_clk     sys_clk            17.000        0.000                      0                    3        0.300        0.000                      0                    3  "}' $S/pos_reverse_row/out/synth_timing_summary.rpt > $S/t && mv $S/t $S/pos_reverse_row/out/synth_timing_summary.rpt; blk guard_clk sys_clk 0 17.000 0.000 0 0.300 0.000 >> $S/pos_reverse_row/out/synth_timing_summary.rpt
                                regen pos_reverse_row "sys_clk:20.000 guard_clk:40.000"; run pos_reverse_row pos "$PASS3"
grep -q 'RECORD other/reverse inter-clock rows' $S/pos_reverse_row.eval.txt && echo "  reverse row recorded for investigation: yes" || { echo "  reverse row recorded: NO"; fails=$((fails+1)); }
base pos_no_forward_row $G1X;   g1ify pos_no_forward_row;   sed -i '/^sys_clk       guard_clk/d' $S/pos_no_forward_row/out/synth_timing_summary.rpt; python3 -I $P/edit_ts.py $S/pos_no_forward_row/out/synth_timing_summary.rpt drop_block - sys_clk guard_clk
                                regen pos_no_forward_row "sys_clk:20.000 guard_clk:40.000"; run pos_no_forward_row pos "COVERAGE=FAIL TIMING=NO-VIOLATION GATE-POSITIVE=PASS STOP"
base pos_no_clock_left $G1X;    g1ify pos_no_clock_left;    sed -i 's/checking no_clock (0)/checking no_clock (5)/' $S/pos_no_clock_left/out/synth_check_timing.rpt
                                regen pos_no_clock_left "sys_clk:20.000 guard_clk:40.000"; run pos_no_clock_left pos "COVERAGE=FAIL TIMING=NO-VIOLATION GATE-POSITIVE=FAIL STOP"
base pos_low_endpoints $G1X;    g1ify pos_low_endpoints;    sed -i 's/^\(guard_clk          12.000        0.000                      0 \)               21000/\1                  26/' $S/pos_low_endpoints/out/synth_timing_summary.rpt
                                regen pos_low_endpoints "sys_clk:20.000 guard_clk:40.000"; run pos_low_endpoints pos "COVERAGE=FAIL TIMING=NO-VIOLATION GATE-POSITIVE=PASS STOP"
base pos_timing17_left $G1X;    g1ify pos_timing17_left;    cp $B/synth_methodology.rpt $S/pos_timing17_left/out/; regen pos_timing17_left "sys_clk:20.000 guard_clk:40.000"; run pos_timing17_left pos "COVERAGE=FAIL TIMING=NO-VIOLATION GATE-POSITIVE=PASS STOP"
base pos_wrong_period $G1X;     g1ify pos_wrong_period;     sed -i 's/^guard_clk  40.000      {0.000 20.000}/guard_clk  20.000      {0.000 10.000}/' $S/pos_wrong_period/out/synth_clocks.rpt
                                regen pos_wrong_period "sys_clk:20.000 guard_clk:20.000"; run pos_wrong_period pos "COVERAGE=FAIL TIMING=NO-VIOLATION GATE-POSITIVE=FAIL STOP"
base pos_not_generated $G1X;    g1ify pos_not_generated;    sed -i 's/^\(guard_clk  40.000      {0.000 20.000}  \)P,G/\1P  /' $S/pos_not_generated/out/synth_clocks.rpt
                                regen pos_not_generated "sys_clk:20.000 guard_clk:40.000"; run pos_not_generated pos "COVERAGE=FAIL TIMING=NO-VIOLATION GATE-POSITIVE=PASS STOP"
base pos_two_generated $G1X;    g1ify pos_two_generated;    sed -i '/^guard_clk  40.000/a extra_clk  80.000      {0.000 40.000}  P,G         {x_reg/Q}' $S/pos_two_generated/out/synth_clocks.rpt
                                regen pos_two_generated "sys_clk:20.000 guard_clk:40.000"; run pos_two_generated pos "COVERAGE=FAIL TIMING=NO-VIOLATION GATE-POSITIVE=PASS STOP"
base pos_unconstrained_listed $G1X; g1ify pos_unconstrained_listed; printf 'Clock Q (endpoints: 5 clock, 0 nonclock)\nFDRE/Q (stray_reg)\n' >> $S/pos_unconstrained_listed/out/synth_clock_networks.rpt
                                regen pos_unconstrained_listed "sys_clk:20.000 guard_clk:40.000"; run pos_unconstrained_listed pos "COVERAGE=FAIL TIMING=NO-VIOLATION GATE-POSITIVE=PASS STOP"
base pos_gate_cw $G1X;          g1ify pos_gate_cw;          printf "CRITICAL WARNING: [Vivado 12-4739] set_false_path:No valid object(s) found for '-from [get_ports x]'. [x.xdc:1]\n" >> $S/pos_gate_cw/out/vivado.log
                                regen pos_gate_cw "sys_clk:20.000 guard_clk:40.000"; run pos_gate_cw pos "COVERAGE=PASS TIMING=NO-VIOLATION GATE-POSITIVE=FAIL STOP"
base pos_wrong_identity $G1X;   g1ify pos_wrong_identity;   regen pos_wrong_identity "sys_clk:20.000 guard_clk:40.000"; sed -i 's/^git_status_sha256 .*/git_status_sha256 0000/' $S/pos_wrong_identity/out/run_manifest.txt
                                run pos_wrong_identity pos "COVERAGE=PASS TIMING=NO-VIOLATION GATE-POSITIVE=PASS STOP"
# --- nc (PREDICTED diagnostic text)
base nc_predicted_pass $NCX;    nc_diag nc_predicted_pass "$ABS" pair;      regen nc_predicted_pass "sys_clk:20.000"; run nc_predicted_pass nc "PASS"
base nc_dup_pair $NCX;          nc_diag nc_dup_pair "$ABS" pair; nc_diag nc_dup_pair "$ABS" pair; regen nc_dup_pair "sys_clk:20.000"; run nc_dup_pair nc "PASS"
base nc_gate_miss $NCX;         nc_diag nc_gate_miss "$ABS" unmatched;      regen nc_gate_miss "sys_clk:20.000"; run nc_gate_miss nc "FAIL — GATE MISS (genuine CRITICAL WARNING not detected; stop, no repair)"
base nc_warning_only $NCX;      nc_diag nc_warning_only "$ABS" warnonly;    regen nc_warning_only "sys_clk:20.000"; run nc_warning_only nc "FAIL — no CRITICAL WARNING at the frozen line"
base nc_wrong_line $NCX;        nc_diag nc_wrong_line "$(pwd)/$NCX:34" pair; regen nc_wrong_line "sys_clk:20.000"; run nc_wrong_line nc "FAIL"
base nc_extra_other_line $NCX;  nc_diag nc_extra_other_line "$ABS" pair; nc_diag nc_extra_other_line "$(pwd)/$NCX:6" pair; regen nc_extra_other_line "sys_clk:20.000"; run nc_extra_other_line nc "FAIL"
base nc_clock_exists $NCX;      nc_diag nc_clock_exists "$ABS" pair;        regen nc_clock_exists "sys_clk:20.000 guard_clk:40.000"; run nc_clock_exists nc "FAIL"
base nc_marker_missing $NCX;    nc_diag nc_marker_missing "$ABS" pair; sed -i '/^SPU_GATE_SCOPE_BEGIN$/d' $S/nc_marker_missing/out/vivado.log; regen nc_marker_missing "sys_clk:20.000"; run nc_marker_missing nc "FAIL"
base nc_completed $NCX;         nc_diag nc_completed "$ABS" pair; regen nc_completed "sys_clk:20.000"; rm -f $S/nc_completed/out/FAILED; echo ok > $S/nc_completed/out/COMPLETE; runner nc_completed COMPLETE; run nc_completed nc "FAIL — GATE MISS (genuine CRITICAL WARNING not detected; stop, no repair)"
echo "EVALUATOR_TESTS $([ $fails -eq 0 ] && echo PASS || echo "FAIL ($fails)")"
[ $fails -eq 0 ]
